"""report.py — 影子日志汇总(上线观测用, 不含任何执行)

  python -m opencode_fastpath.report [--dir logs] [--today]
"""
from __future__ import annotations

import argparse
import json
import time
from pathlib import Path

HERE = Path(__file__).resolve().parent


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--dir", default=str(HERE / "logs"))
    ap.add_argument("--today", action="store_true")
    args = ap.parse_args()
    d = Path(args.dir)
    files = sorted(d.glob("decisions-*.jsonl"))
    if args.today:
        files = [p for p in files if time.strftime("%Y%m%d") in p.name]
    if not files:
        print(f"(没有日志: {d})")
        return
    tot = hit = miss = unknown = rescue = 0
    lat = []
    for p in files:
        for line in p.read_text(encoding="utf-8").splitlines():
            try:
                r = json.loads(line)
            except Exception:
                continue
            tot += 1
            if r.get("fp") == "hit":
                hit += 1
            else:
                miss += 1
            if r.get("model_intent") == "unknown":
                unknown += 1
            if r.get("rescue"):
                rescue += 1
            if r.get("fp_latency_us"):
                lat.append(r["fp_latency_us"])
    lat.sort()
    p95 = lat[int(len(lat) * 0.95)] if lat else 0
    print(f"决策样本 {tot}")
    print(f"  快路径命中 {hit} / MISS {miss}")
    print(f"  原逻辑 unknown {unknown} → 可救回(rescue) {rescue}"
          + (f"  占 unknown 的 {100*rescue/unknown:.1f}%" if unknown else ""))
    if lat:
        print(f"  快路径耗时 mean {sum(lat)/len(lat):.1f}µs  p95 {p95:.1f}µs")


if __name__ == "__main__":
    main()
